self.addEventListener("push",i=>{if(!i.data)return;let n=i.data.json(),t=n.title||"Expenso",e={body:n.body,icon:"/icons/icon-192.png",badge:"/icons/icon-192.png",data:{url:n.url||"/"},vibrate:[100,50,100]};i.waitUntil(self.registration.showNotification(t,e))}),self.addEventListener("notificationclick",i=>{i.notification.close();let n=i.notification.data?.url||"/";i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{let t=i.find(i=>i.url.includes(n));return t?t.focus():self.clients.openWindow(n)}))});